import pandas as pd

def group_summary(df: pd.DataFrame) -> pd.DataFrame:
    return df.groupby("category").agg(
        total=("amount", "sum"),
        average=("amount", "mean")
    ).reset_index()

import pandas as pd

def pivot_data(df: pd.DataFrame) -> pd.DataFrame:
    return df.pivot(index="city", columns="month", values="temperature").reset_index()

import pandas as pd

def clean_data(df: pd.DataFrame) -> pd.DataFrame:
    df = df.drop_duplicates(subset=["id"], keep="first")
    df["quantity"] = df["quantity"].fillna(0)
    return df.dropna(subset=["price"]).reset_index(drop=True)

import pandas as pd

def inspect_dataframe(df: pd.DataFrame) -> list:
    return [df.shape[0], df.shape[1]]

import pandas as pd

def concat_and_sort(df1: pd.DataFrame, df2: pd.DataFrame) -> pd.DataFrame:
    combined = pd.concat([df1, df2], ignore_index=True)
    return combined.sort_values(by="salary", ascending=False).head(5).reset_index(drop=True)

